using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Foundation;

internal sealed class OriginalWidthContactDocument : IScribeDocumentDefinition
{
    private const string Owner = "D5/S3/Quantum/Foundation/OriginalWidthContact.";
    private static Formula V(string s) => F.Id(s);
    private static Formula C(string s, params Formula[] xs) => new Formula.FunctionCall(FormulaIdentifier.Create(s), [.. xs]);
    private static Formula All(string s, Formula t, Formula b) => new Formula.Bind(FormulaQuantifier.ForAll, FormulaIdentifier.Create(s), t, b);
    private static Formula Ex(string s, Formula t, Formula b) => new Formula.Bind(FormulaQuantifier.Exists, FormulaIdentifier.Create(s), t, b);
    private static Formula Eq(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.Equal, b);
    private static Formula Imp(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.Implies, b);
    private static Formula And(params Formula[] xs) => xs.Length == 1 ? xs[0] : new Formula.Logic(xs[0], FormulaLogicOperator.And, And(xs[1..]));
    private static Formula In(Formula a, Formula b) => Seq(a, InMacro, Sp, b);
    private static Formula Ne(Formula a, Formula b) => Seq(a, Neq, Sp, b);
    private static Formula Lt(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.LessThan, b);
    private static Formula Le(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.LessThanOrEqual, b);
    private static Formula App(Formula f, Formula x) => C("apply", f, x);
    private static Formula Sub(Formula x, Formula y) => C("sub", x, y);
    private static Formula R => Seq(Mathbb, Grp(V("R")));
    private static Formula Space => V("V");
    private static Formula Dual => C("LinearMap", R, Space, R);
    private static Formula K => C("base", V("C"), V("u"));
    private static Formula P => C("pure", V("C"), V("u"));
    private static Formula Dp(Formula p) => C("exclusion", V("C"), V("u"), p);
    private static Formula Proper(Formula f) => C("proper", V("C"), V("u"), f);
    private static Formula WB(Formula face, Formula m) => C("WidthBound", V("C"), V("u"), face, m);
    private static Formula Context(Formula body) => All("V", V("Type"), Seq(
        OpenBracket, C("NormedAddCommGroup", Space), CloseBracket, Sp,
        OpenBracket, C("NormedSpace", R, Space), CloseBracket, Sp,
        OpenBracket, C("FiniteDimensional", R, Space), CloseBracket, Sp,
        All("C", C("PointedCone", R, Space), All("u", Dual, body))));
    private static Formula BasicContext(Formula body) => All("V", V("Type"), Seq(
        OpenBracket, C("NormedAddCommGroup", Space), CloseBracket, Sp,
        OpenBracket, C("NormedSpace", R, Space), CloseBracket, Sp,
        All("C", C("PointedCone", R, Space), All("u", Dual, body))));

    public DocumentDefinition Create()
    {
        Formula p = V("p"), q = V("q"), r = V("r"), m = V("M"), b = V("b"), e = V("e");
        Formula xy = V("xy"), zw = V("zw"), x = C("fst", xy), y = C("snd", xy);
        Formula z = C("fst", zw), w = C("snd", zw);
        Formula Contact(Formula a, Formula c) => And(In(a, K), In(c, K),
            Eq(App(b, a), D(1)), Eq(App(b, c), D(0)),
            Eq(Sub(q, r), C("smul", m, Sub(a, c))));
        Formula strict = All("x", Space, Imp(In(V("x"), V("C")),
            Imp(Ne(V("x"), D(0)), Lt(D(0), App(V("u"), V("x"))))));
        Formula inj = All("p1", P, All("p2", P,
            Imp(Eq(Dp(V("p1")), Dp(V("p2"))), Eq(V("p1"), V("p2")))));
        Formula zero = All("z", Space, Imp(In(V("z"), Dp(p)), Eq(App(e, V("z")), D(0))));
        Formula readings = Imp(Lt(m, D(1)), All("e", Dual,
            Imp(C("confirms", V("C"), V("u"), p, e), Imp(zero,
                And(Lt(D(0), App(e, x)), Eq(App(e, x), App(e, y)), Lt(App(e, y), D(1)),
                    C("not", In(x, Dp(p))), C("not", In(y, Dp(p))))))));
        Formula conclusion = Ex("xy", C("Prod", Space, Space), And(Contact(x, y),
            All("zw", C("Prod", Space, Space), Imp(Contact(z, w), Eq(zw, xy))), readings));
        Formula full = Context(All("b", Dual, Imp(And(C("IsClosed", V("C")), strict,
            Eq(C("span", R, V("C")), C("top")), C("exclusionBalls", V("C"), V("u")), inj),
            All("p", P, All("M", R, Imp(Lt(D(0), m), Imp(WB(Dp(p), m), Imp(Proper(b),
                All("q", Space, All("r", Space, Imp(And(In(q, Dp(p)), In(r, Dp(p)),
                    Eq(Sub(App(b, q), App(b, r)), m)), conclusion)))))))))));
        Formula width = BasicContext(All("F", C("Set", Space), All("M", R,
            new Formula.Logic(WB(V("F"), m), FormulaLogicOperator.Iff,
                All("f", Dual, Imp(Proper(V("f")), All("x", Space, All("y", Space,
                    Imp(And(In(V("x"), V("F")), In(V("y"), V("F"))),
                        Le(Sub(App(V("f"), V("x")), App(V("f"), V("y"))), m))))))))));
        return DocumentDefinition.Create(ScribeNode.Create(
            "Every positive attained width on a whole original exclusion face determines one unique actual joint contact pair, with strict equal readings for all confirming effects when the width is below one.",
            H("The unique joint contact pair of an attained original width"), Blocks(
                Paragraph(Text("V is an arbitrary finite dimensional real normed space. C is the original closed generating pointed convex cone, u is strictly positive on its nonzero vectors, K is the entire slice C intersect {u=1}, and P comprises every extreme point of K. Every effect is an original real-linear functional satisfying 0<=f<=u on the whole cone. Every entire exclusion D(p) is an injective affine image of a nondegenerate finite Euclidean closed ball, and equality of two such original exclusions forces equality of their pure labels. The result includes the original three-dimensional ball case. No inner product on V, closedness or compactness of P, pair-face hypothesis, unique confirmation premise or retraction is required.")),
                Paragraph(Text("Application: adjacent complete confirmation and the original normalized perturbation.")),
                Paragraph(Text("Keep this same entire K, cone, unit, full effect interval and injective exclusion-ball family. Fix arbitrary original pure labels p,q with q in F=D(p), and arbitrary complete confirmers a of q and e of p: a and e are proper, a(q)=e(p)=1, a vanishes on all of D(q), and e vanishes on all of F. The original sphere condition q in S(F) supplies such a pure q because F is an extreme face of K and the extreme points of a nondegenerate Euclidean ball are its sphere. Suppose M<1 and WidthBound(C,u,D(q),M). In the original global-width notation, W(D(r)) is the maximum oscillation over every proper original effect and M=sup_r W(D(r)); then f(x)-f(y)<=osc_D(q)(f)<=W(D(q))<=M for every proper original f and all x,y in D(q). This supplies precisely the local WidthBound premise, without restricting the effect domain or replacing the global supremum by a different quantity. The argument below applies to every such p,q,a,e.")),
                Paragraph(Text("Use top_subsingleton_of_zero_exclusion with the label q and effect a. Since a(q)=1, its whole one-value face is {q}. If y is any zero of a in K, the definition of exclusion puts y in D(q). Exclusion symmetry (FacetZeroGluing.exclusion_symmetric) gives p in D(q), so the width bound for the same original e gives 1-e(y)<=M and hence e(y)>=1-M>0. Also e(q)=0. Thus for every x,y in K with a(x)=1 and a(y)=0, e(x)<e(y). Only this inclusion of the zero face in D(q) is needed; no extra equality of faces is assumed.")),
                Paragraph(Text("There is an elementary compact-extrema route to the required perturbation. On the compact nonempty set T={(x,y) in K times K : e(y)<=e(x)}, let d=max_T(a(x)-a(y)). Compactness follows from base_compact, the compact-product and closed-intersection rules, and continuity of the two original effects; IsCompact.exists_isMaxOn supplies an actual maximizing pair. The diagonal makes T nonempty. The effect bounds give d<=1. Equality would force a(x)=1 and a(y)=0 at that pair, contradicting the preceding strict contact inequality. Hence d<1. Put t=(1-d)/2>0 and g=a+t e. If e(y)<=e(x), then g(x)-g(y)<=d+t=(1+d)/2<1. Otherwise t(e(x)-e(y))<0 and a(x)-a(y)<=1, again giving g(x)-g(y)<1. These are applications of compact extrema and real inequalities, with no differentiation of a moving family.")),
                Paragraph(Text("Take the actual minimum lo and maximum hi of this same g on the entire K, using IsCompact.exists_isMinOn and IsCompact.exists_isMaxOn, and set s=hi-lo. Their ordered pair gives s<1. The original exclusion_ball_faces result makes F a nondegenerate compact ball. Choose r in F distinct from q. Whole-face rigidity gives a(r)<a(q)=1, while e is zero on all of F, so g(q)-g(r)=1-a(r)>0 and therefore s>0. Define the original real-linear functional b=(g-lo u)/s. Its bounds 0<=b<=1 on K imply 0<=b<=u on the whole original cone by positive-unit rescaling, exactly as in the existing normalized_effect proof and CircuitBalancedConfirmation.cone_bound. Thus b belongs to the original full effect interval, with no change of unit or restriction of state space.")),
                Paragraph(Text("On the entire F, g=a because e vanishes there. Its normalization therefore gives osc_F(b)=osc_F(a)/s. Compactness supplies the actual extrema on F, and the same q,r show osc_F(a)>0. Since 0<s<1, osc_F(b)>osc_F(a)>0. This derives the original adjacent-complete-confirmation conclusion and the specified formula b=(a+t e-(min_K(a+t e))u)/(max_K(a+t e)-min_K(a+t e)). The minimum, maximum and positive parameter all refer to one common original realization. The compact-extrema results used here are in pinned Mathlib (Mathlib.Topology.Order.Compact); the full-cone and whole-face premises come from the existing project results.")),
                Paragraph(Text("This route establishes the finite positive-parameter conclusion within the stated convex model. It does not establish the distinct one-sided expansions max_X(b+t h)=max_X(b)+t max_argmax(b)(h)+o(t) and min_X(b+t h)=min_X(b)+t min_argmin(b)(h)+o(t) for arbitrary continuous b,h on an arbitrary nonempty compact X. In particular the perturbation argument alone supplies neither derivative statement. The perturbation is a conditional deduction in the full-effect convex model.")),
                Paragraph(Text("Application: the original regular pentagon and all five complete exclusions.")),
                Paragraph(Text("Use the mass-first carrier V5=R times (R times R), the vertices p_j=(1,cos(2 pi j/5),sin(2 pi j/5)), their entire convex hull K5, its conic hull C5 and u5(t,x,y)=t. Indices are modulo five. The effect domain is every real-linear f with 0<=f<=u5 on all of C5. On the mass-one plane an arbitrary affine function a homogenizes as f(t,z)=t a(0)+a.linear(z); restriction f(1,z) is the inverse correspondence. Thus bounds on the entire K5 and properness on the entire C5 correspond, including the zero vector. The carrier and unrestricted-effect interpretation is the one in Library/FiniteGeometry/janottagogolinbarrettbrunner2011polygon.md and takakura2020polygonentropy.md, after permuting the mass coordinate. Neither the thermodynamic conclusions nor composite-state assumptions of those papers enter this application.")),
                Paragraph(Text("Put c=cos(pi/5), d=cos(2 pi/5), tau=sin(pi/5), sigma=sin(2 pi/5), phi=goldenRatio and M=1/phi. The exact vertex list is (1,1,0), (1,d,sigma), (1,-c,tau), (1,-c,-tau), (1,d,-sigma). PentagonCosines.pentagon_golden_cosines and the double-angle identity give 2c=phi, 2d=M, sigma=phi tau and M squared plus M equals one. In particular tau,sigma,c,d,M are positive, 1/2<M<1 and 1-M<M. These are uses of existing golden and trigonometric identities.")),
                Paragraph(Text("PointedCone.mem_hull_set expresses every cone member as a nonnegative combination of the five vertices. Its mass is the sum of its coefficients. Mass one is therefore exactly K5, and a nonzero cone member has strictly positive mass. This also proves salience. Conversely any nonnegative multiple of a point of K5 is in the cone, and a nonzero cone member divided by its mass is in K5, so the vertex-generated cone equals cone(K5). The determinant of the columns p1,p3,p4 is 2 sigma(c+d)>0, proving generation of V5. Closedness is the finite-generator cone result, also supplied by the compact normalized-base argument in the cited polygon note.")),
                Paragraph(Text("Rotation Q_j(t,x,y)=(t,cos(theta_j)x-sin(theta_j)y,sin(theta_j)x+cos(theta_j)y), theta_j=2 pi j/5, has inverse Q_(-j), preserves u5 and sends p_i to p_(i+j). The addition and periodicity identities prove these statements on the actual Cartesian carrier. LinearMap.image_convexHull and nonnegative conic combinations give Q_j(K5)=K5 and Q_j(C5)=C5. Consequently f maps to f composed with Q_(-j) bijects the whole proper-effect interval, every confirming fiber and every common-confirmer fiber. The horizontal functional exposes p0 uniquely: its values are 1,d,-c,-c,d with d<1. SymmetricBellPolytopeSupport.exposed_hull_of_unique_max and IsExposed.isExtreme make p0 pure. Rotation gives every p_j pure, while Mathlib extremePoints_convexHull_subset excludes every other pure point.")),
                Paragraph(Text("Here is the whole-state zero-set argument, retaining all original confirmers. If f is any proper confirmer of p0, evaluation of p0-p1=M(p4-p2) and p0-p4=M(p1-p3), with all five proper readings between zero and one, forces f(p1)>0 and f(p4)>0; also f(p0)=1. All zero-valued generators therefore lie in {p2,p3}. The frozen ZeroTraceHull.zero_trace_hull gives the entire zero trace as their convex hull. Its four-coordinate carrier is used by the injective linear padding E(t,x,y)=(t,x,y,0), the left inverse P taking the first three coordinates, and the support -f composed with P. All generator support values are nonpositive. LinearMap.image_convexHull and P composed with E equal to the identity transport the resulting whole-hull zero trace back to V5. If one or both of the two remaining readings are positive, the zero trace only shrinks, so it is always contained in [p2,p3]. This is a direct existing-owner application, rather than a new convex-closure lemma.")),
                Paragraph(Text("The actual effect e0(t,x,y)=(x+c t)/(1+c) has vertex readings (1,M,0,0,M). Nonnegative conic combinations establish its whole-cone properness, and it vanishes on every point of [p2,p3]. It supplies the reverse exclusion inclusion. Thus D(p0)=[p2,p3]; rotation of the full state and effect domains gives D(p_j)=[p_(j+2),p_(j+3)] for all five j. The chart chi_j(w)=(p_(j+2)+p_(j+3))/2+w(p_(j+2)-p_(j+3))/2 is injective on all of R and maps the entire closed unit interval onto D(p_j). The standard singleton orthonormal basis identifies this R isometrically with EuclideanSpace R (Fin 1), giving actual ExclusionChart objects with dimension one. The exposed pure endpoints of two equal segments must be the same unordered pair of vertices; the five cyclic unordered pairs are distinct. Hence equality of the whole exclusions forces equality of their pure labels. This supplies EB1 and Inj on every pure point.")),
                Paragraph(Math(Disp(All("j", C("Fin", D(5)), And(
                    Eq(C("exclusion", V("C5"), V("u5"), C("p5", V("j"))),
                        C("segment", R, C("p5", C("addMod5", V("j"), D(2))), C("p5", C("addMod5", V("j"), D(3))))),
                    Eq(C("width", V("C5"), V("u5"), C("exclusion", V("C5"), V("u5"), C("p5", V("j")))), m)))))),
                Paragraph(Text("Set p=p0, F=D(p0), q=p2, r=p3, s=p1 and y=p4. The original effect b5(t,x,y)=(y+sigma t)/(2 sigma) has vertex readings (1/2,1,(1+M)/2,(1-M)/2,0). It is proper on the full cone. The unique-maximum hull owner, applied also to its negative, identifies its entire top and zero faces as {p1} and {p4}. The actual vector identity p2-p3=M(p1-p4) implies |f(p2)-f(p3)|<=M for every original proper f. The image_segment and segment_eq_Icc' identities, followed by csSup_Icc and csInf_Icc, identify oscillation on the whole edge with the absolute endpoint difference. For b5 this difference is M. The supremum over all proper effects is therefore exactly M and is attained by b5. Pullback by each Q_j bijects all effects and preserves their image sets on the transported edge, so every one of the five full-effect supremum widths is M. The same b5, s,y and chord are retained for the selected F.")),
                Paragraph(Text("Write e_j=e0 composed with Q_(-j). Every common confirmer of p_j is exactly e_j: it takes value one at p_j and zero at both endpoints of its whole exclusion, and these three linearly independent homogeneous states determine a real-linear functional. The e_j have the stated properties on every point of those exclusions. In particular the entire common fiber at p0 is {e0}, with e0(s)=e0(y)=M. This does not make the larger fiber of all effects merely confirming p0 a singleton. At s=p1 the common fiber is {e1}, with vertex readings (M,1,M,0,0). Thus G=D(s)=[p3,p4]. Its whole zero face is G and its whole top face is {s}. The F chart chi_F(w)=(p2+p3)/2+w(p2-p3)/2 has n=1; choose chi_G(z)=(p3+p4)/2+z(p4-p3)/2, so eta=1 and chi_G(eta)=y. These charts have their own scalar coordinates, each realized through EuclideanSpace R (Fin 1). Since e1(chi_F(w))=M(1+w)/2, F meets its zero face G exactly at r=p3. All the named endpoints are original pure points.")),
                Paragraph(Text("The actual normal cone, whole-chart inverse and A–E correspondences.")),
                Paragraph(Text("Let N1 be every original positive real-linear functional annihilating s, and H1 its actual real span. For any signed h with h(p1)=0 put a=h(p3), b=h(p4), alpha=(a+b)/2 and v=(b-a)/2. The same two chord identities give h(p0)=b-Ma and h(p2)=a-Mb. The determinant above makes these readings complete coordinates on the annihilator of p1. Positivity on the entire original cone is consequently equivalent to a>=0, b>=0, a>=Mb and b>=Ma. Equivalently alpha>=(1+M)|v|/(1-M). No assertion that positivity on G alone suffices is used.")),
                Paragraph(Math(Disp(Eq(C("vertexReadings", V("h")), C("tuple",
                    Sub(V("b"), C("mul", m, V("a"))), D(0),
                    Sub(V("a"), C("mul", m, V("b"))), V("a"), V("b")))))),
                Paragraph(Text("The actual e3 and e4 belong to N1 and have (a,b) readings (1,M) and (M,1). Since 1-(M squared)=M>0, they are independent and span the full annihilator. More precisely h=((a-Mb)/M)e3+((b-Ma)/M)e4. Thus N1 is exactly their nonnegative conic hull, H1 is exactly {h:h(s)=0}, and H1 has real dimension two. Restriction to the entire G chart is R(h)(z)=alpha+vz. Every affine function on the one-dimensional chart has unique alpha,v, and its unique signed inverse is h=(((1-M)alpha-(1+M)v)/M)e3+(((1-M)alpha+(1+M)v)/M)e4. These equalities hold on all chart coordinates, including outside the ball, so this is the actual linear restriction isomorphism to the full affine-function space, not only a two-reading identification. AffineMap.toConstProdLinearMap and AffineMap.finrank_eq give the same target dimension two. Its positive image is precisely the narrower cone alpha>=(1+M)|v|/(1-M). The constant-one slice of N1 is the singleton u5-e1; its two cone coefficients are M>0, so it lies in the relative interior in H1.")),
                Paragraph(Math(Disp(Eq(C("inverseRestriction", V("alpha"), V("v")), C("add",
                    C("smul", C("div", Sub(C("mul", Sub(D(1), m), V("alpha")), C("mul", C("add", D(1), m), V("v"))), m), V("e3")),
                    C("smul", C("div", C("add", C("mul", Sub(D(1), m), V("alpha")), C("mul", C("add", D(1), m), V("v"))), m), V("e4"))))))),
                Paragraph(Text("A: quantify the entire common fiber at s, which is {e1}. Its F restriction M(1+w)/2 has oscillation M and slope (M/2)n, with the unique ball maximum q and minimum r. Its entire original top and zero faces are {s} and G. The same s,y obey e1(s)=1, e1(y)=0 and q-r=M(s-y). Any other joint contact pair with this chord has first member s by the whole top-face statement and then second member y by the vector equality. Thus a larger zero face causes no ambiguity in the joint pair.")),
                Paragraph(Text("B: on the actual H1 the F slope is S_F(h)=(h(p2)-h(p3))/2=-M(alpha+v)/2. R is the preceding whole-G restriction, so its kernel is zero and S_F factors uniquely as T(alpha,v)=-M(alpha+v)/2. This is the one-dimensional instance of T(alpha,v)=-(M/2)(alpha+eta v)n+L(v), with n=eta=1. The actual perpendicular space to n in the F chart is {0}, so the unique transverse map L is zero. In carrier terms ker R is H1 intersect the annihilator of span G and is zero; ker S_F is {h in H1:h(p4)=0}. The coannihilator of H1 is span{p1}, and the actual F direction p2-p3=M(p1-p4) belongs to span G plus span{p1}. These direct coordinate identities do not invoke the EB3 theorem OriginalNormalRestriction or the general Proposition 122.3.")),
                Paragraph(Text("Both original normalizations keep the full cone and the same unit. For any original signed g let lo and hi be the minimum and maximum of its five readings. Affine convex-hull transport identifies these with its minimum and maximum on the whole K5. If hi>lo, (g-lo u5)/(hi-lo) is a proper effect on all of C5. If hi=lo, generation gives g=lo u5; no division is made. For h in N1, its minimum is zero at s, and its maximum is max(a,b)=alpha+|v|: the other nonzero readings b-Ma and a-Mb are respectively no larger than b and a. If h is nonzero, this maximum lambda is strictly positive, and f_h=h/lambda is an actual full-cone effect. If h=0, alpha=v=0 and all oscillations and homogeneous inequalities are zero; normalization is reserved for the nonzero case.")),
                Paragraph(Text("C: for every such nonzero actual h, osc_G(f_h)=2|v|/lambda and osc_F(f_h)=M|alpha+v|/lambda=2|T(alpha,v)|/lambda, because the formulas hold on the entire two chart balls. Their full widths M give alpha>=(2/M-1)|v| and 0<=M squared times ((alpha+|v|) squared minus (alpha+v) squared), the quadratic inequality with L(v)=0. The exact actual image slice B_s={v:there is h in N1 with R(h)=(1,v)} is [-rho,rho], rho=(1-M)/(1+M)>0. The displayed signed inverse is positive exactly on this interval, so the slice has actual witnesses in both directions, including v=0 and its boundary. Since M>1/2, rho<=M/(2-M), giving the width radial bound. Also (1+v) squared <= (1+|v|) squared on this actual slice. These are the two C inequalities for every feasible normal; they assert no positive lift for arbitrary signed chart data.")),
                Paragraph(Math(Disp(Eq(V("Bs"), C("Icc", C("neg", C("div", Sub(D(1), m), C("add", D(1), m))),
                    C("div", Sub(D(1), m), C("add", D(1), m))))))),
                Paragraph(Text("D: the same second contact is the original pure y=p4, at eta=1 on the actual G chart, and |eta|=1. The endpoint rho of the preceding image slice supplies a strictly positive ray witness with v=rho eta. The actual transverse L is zero, so L(eta)=0. All these statements use the same contact and the full normal family, with no choice of a replacement pure endpoint.")),
                Paragraph(Text("E: the actual intersection is {r}={p3}, and D(r)=[p0,p1] contains p and s. Its full width and the full width of G both equal M. Quantify the entire common fiber at p, namely {e0}: t_e=e0(s)=e0(y)=M, while osc_G(e0)=M and osc_D(r)(e0)=1-M<M. Hence 0<t_e<1, 1-W(D(r))<t_e<=W(G), W(G)+W(D(r))=2M>1 and M>1/2. This realizes equality in the pure-y upper bound. There is no mixed-y instance in this fixed configuration.")),
                Paragraph(Text("This is an application derivation using the existing hull/exposure, finite-dimensional affine and linear algebra, trigonometric, segment-extrema and golden-ratio results. The kernel certificate attached to original_width_contact below is the general contact theorem; it is not a separate compiled certificate of all these pentagon coordinate correspondences. Each exclusion chart here has dimension one. The calculation supplies no EB3 model, logical-independence result, physical instrument, unit-preserving positive retraction or literature-originality claim. The polygon literature supplies the carrier and effect inputs; the full-width and normal-coordinate derivation is the stated elementary application.")),
                Describe.Lean(DescribeId.Create("top-exposed"), DeclarationHandle.Create(Owner + "top_exposed"), H("The whole original one-value face is exposed"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The one-value set of any original proper effect is an exposed face of the entire original base. The density label-limit proof uses this original-site result to derive purity of a cluster point after showing that this whole face is a singleton."))), DescribeRole.Theorem),
                Describe.Lean(DescribeId.Create("top-subsingleton"), DeclarationHandle.Create(Owner + "top_subsingleton_of_zero_exclusion"), H("Whole one-value-face rigidity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("With the original closed generating cone, strictly positive unit, full positive-dimensional exclusion balls and injective original exclusion map, any proper original effect vanishing on the entire D(p) has a subsingleton whole one-value face. Its actual pure maximizers all have the same full exclusion as p; injectivity and compact convex generation then control every state in that face. The label-limit proof starts its limit state in K and uses this whole-face result, without assuming that the state is pure."))), DescribeRole.Theorem),
                Describe.Lean(DescribeId.Create("width-bound"), DeclarationHandle.Create(Owner + "WidthBound"),
                    H("The full effect width bound"), StatementSource.FromAuthor(Disp(width)),
                    AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("WidthBound(C,u,F,M) quantifies every original effect and every ordered pair of points of the entire F. Together with b(q)-b(r)=M for one proper b and q,r in F, it says exactly that M is the attained maximum ordered contrast. Thus it expresses W(F)=M without choosing a smaller effect or state domain."))), DescribeRole.Definition),
                Describe.Lean(DescribeId.Create("original-width-contact"), DeclarationHandle.Create(Owner + "original_width_contact"),
                    H("One actual pair, uniqueness and all strict confirming readings"),
                    StatementSource.FromAuthor(Disp(full)), AssessedProvenance.FromRepo(), Blocks(
                        Paragraph(Text("Fix the original p, F=D(p), M>0, an effect b and points q,r in F attaining the full width M. The conclusion selects one ordered pair (x,y) of original states. It has b(x)=1, b(y)=0 and q-r=M(x-y). Every other ordered pair with these same properties equals it. If M<1, this same pair satisfies 0<e(x)=e(y)<1 for every original confirmer e of p which vanishes on all of F. Both points are then outside F. No claim says that both contacts are pure or that different maximizing b have the same contacts.")),
                        Paragraph(Text("For an arbitrary continuous linear functional h, compactness supplies its actual minimum a and maximum z on K. If its oscillation s=h(z)-h(a) is positive, the full-cone effect (h-h(a)u)/s has contrast at most M on q,r. Hence h((q-r)/M)<=s. If s=0, h(q)=h(r), giving the same inequality. The closed convex set K-K is the intersection of its containing half-spaces, so the same vector (q-r)/M lies in K-K. This gives one actual pair x,y in K. Its b contrast equals one, and the original effect bounds force b(x)=1 and b(y)=0. In particular the resulting member of X-Y satisfies every directional support inequality for X-Y; no directional optimizers are combined.")),
                        Paragraph(Text("For any original full-amplitude effect, its two contact sets are compact convex faces. If the zero face is not a pure singleton, the original proper-face classification makes it an entire D(t). For every pure s in the one face, the same effect puts D(t) inside D(s). Whole-ball facial rigidity and injectivity of the exclusion labels force s=t. Krein-Milman then makes the entire one face a singleton. Thus at least one contact face is a singleton, and the fixed difference uniquely determines the other endpoint.")),
                        Paragraph(Text("Every confirmer e vanishing on F annihilates q-r, so both contacts have equal readings. A common zero reading would put both contacts in F, where the original b would have contrast one, contradicting its full width M<1. A common reading one puts both contacts in the singleton one face of e, contradicting their b readings one and zero. This proves the strict bounds for all such e after the single pair has been fixed.")),
                        Paragraph(Text("For the global maximum-width application, take the whole F supplied by the positive attained global maximum in the original width theorem 118.15 and use the same attained b and its actual two extrema. No new global maximum theorem is asserted here. The local conclusion applies to every positive attained whole-face width and requires no restriction of p to uniquely confirmed labels. It does not produce a common exclusion ball containing the two contacts, does not force M=1 and does not establish the global width-one or dense-triangle condition. This is a deduction in the specified full-effect convex model, with no claim of literature priority or physical instrument realization."))), DescribeRole.Theorem))));
    }
}
